ALTER DATABASE "rsd-db" SET JIT = OFF;

-- PLANT-COMMONS: no password here, the platform sets it (CNPG managed role)
CREATE ROLE rsd_authenticator NOINHERIT LOGIN;

CREATE ROLE rsd_web_anon NOLOGIN;

GRANT USAGE ON SCHEMA public TO rsd_web_anon;

ALTER DEFAULT PRIVILEGES FOR ROLE rsd IN SCHEMA public GRANT SELECT ON TABLES TO rsd_web_anon;

GRANT rsd_web_anon TO rsd_authenticator;

CREATE ROLE rsd_admin NOLOGIN;

ALTER DEFAULT PRIVILEGES FOR ROLE rsd IN SCHEMA public GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO rsd_admin;

GRANT rsd_admin TO rsd_authenticator;

CREATE ROLE rsd_user NOLOGIN;

ALTER DEFAULT PRIVILEGES FOR ROLE rsd IN SCHEMA public GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO rsd_user;

GRANT rsd_user TO rsd_authenticator;

-- PLANT-COMMONS: from here on the schema is created by the owner role (owns the objects, holds the default privileges above)
SET ROLE rsd;

