	AND
	COALESCE(participating_organisations, '{}') @> organisation_filter
	AND
	COALESCE(categories, '{}') @> category_filter
	AND
		CASE
			WHEN status_filter <> '' THEN project_status = status_filter
			ELSE true
		END
GROUP BY
	category
;
$$;

