-- REACTIVE LICENSES FILTER WITH COUNTS FOR SOFTWARE
-- PROVIDES AVAILABLE LICENSES FOR APPLIED FILTERS
CREATE FUNCTION org_software_categories_filter(
	organisation_id UUID,
	search_filter TEXT DEFAULT '',
